entries[65435] = { ["name"] = "Rezept: Schlachtzugskessel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Schlachtzugskessel zubereitet.\nBenötigt Alchemie des Kataklysmus\n(75)\n\nSchlachtzugskessel\nWird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 10 Anwendungen und bleibt 10 Min. lang bestehen.\nBenötigt Gilde\n- Freundlich\nVerkaufspreis:\nBenötigt Fläschchen der Stahlhaut , Fläschchen der drakonischen Gedanken , Fläschchen der Winde , Fläschchen der Titanenstärke , Todesblutgift (8)" }
entries[65455] = { ["name"] = "Fläschchen des Schlachtzugs", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Gildenfläschchen (1)\nBenutzen: Gewährt den Effekt eines Fläschchens basierend auf Eurer Klasse und Euren Talenten. Hält 1 Stunde lang an und hält über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[65460] = { ["name"] = "Großer Schlachtzugskessel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nBenötigt Gilde\n- Freundlich\nVerkaufspreis:" }
