entries[66099] = { ["name"] = "Pläne: Obsidiumdietrich", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Obsidiumdietrichs.\nBenötigt Schmiedekunst (425)\n\nObsidiumdietrich\nBenutzen: Ermöglicht das Öffnen von Schlössern, die eine Fertigkeit von bis zu 35 im Schlossknacken benötigen. Dieser Vorgang verbraucht den Dietrich.\nBenötigt Schmiedekunst des Kataklysmus (25)\nVerkaufspreis:\nBenötigt Gefaltetes Obsidium (2)" }
entries[66100] = { ["name"] = "Pläne: Gürtelschnalle aus Schwarzstahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer Gürtelschnalle aus Schwarzstahl.\nKann nicht auf Gegenstände über Stufe 49 angewandt werden.\nBenötigt Schmiedekunst des Kataklysmus (75)\n\nGürtelschnalle aus Schwarzstahl\nBenutzen: Bringt dauerhaft eine Gürtelschnalle aus Schwarzstahl an einem Gürtel an und fügt ihm so einen Sockel hinzu.\n\nDurch das Anbringen der Gürtelschnalle wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände der Stufe 0 oder höher angewandt werden.\nVerkaufspreis:\nBenötigt Flüchtige Erde (4), Elementiumbarren (4), Pyriumbarren (4)" }
entries[66101] = { ["name"] = "Pläne: Pyriumschildstachel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Pyriumschildstachels.\nBenötigt Schmiedekunst des Kataklysmus (75)\n\nPyriumschildstachel\nWird beim Anlegen gebunden\nBenutzen: Bringt einen Pyriumstachel an Eurem Schild an, der beim Blocken manchmal 42 Schaden verursacht.\n\nDurch das Anbringen des Pyriumschildstachels wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Pyriumbarren (5)" }
entries[66102] = { ["name"] = "Pläne: Elementiumschildstachel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Elementiumschildstachels.\nBenötigt Schmiedekunst (425)\n\nElementiumschildstachel\nBenutzen: Bringt einen Elementiumstachel an Eurem Schild an, der bei jedem Blocken 4 Schaden verursacht.\n\nDurch das Anbringen des Elementiumschildstachels wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Elementiumbarren (15)" }
entries[66103] = { ["name"] = "Pläne: Pyriumwaffenkette", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer Pyriumkette.\nBenötigt Schmiedekunst des Kataklysmus (50)\n\nPyriumwaffenkette\nWird beim Anlegen gebunden\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert und Euer Tempo um 12 erhöht. Ist nicht mit ähnlichen Effekten stapelbar. Durch das Anbringen der Waffenkette wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Pyriumbarren" }
